      .wc-pane-separator::after { top: 2px; left: calc(50% - 12px); width: 24px; height: 5px; border-inline: 0; border-block: 1px solid var(--wc-line-strong); }
      .wc-table th.perms, .wc-table td.perms { display: none; }
